using System.Text;
using System.Text.Json;
internal sealed record LibraryPackageDocument(LibraryDocumentVersion Identification,string EvidenceHash);
internal sealed record LibraryPackagePreparation(string Id,string? ProjectId,string IntakeId,int LineNumber,string DisplayId,string IncomingRevision,string SourceFingerprint,int? RequestedQuantity,string? RequestedScope);
internal sealed record LibraryPackageVersion(string Id,int Version,string Status,LibraryBomDraft Bom,LibraryPackageDocument[] Documents,string ContentHash,LibraryActor SubmittedBy,LibraryPackagePreparation? Preparation=null,LibraryActor? ReviewedBy=null,string? Comments=null,LibraryActor? WithdrawnBy=null,[property: System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] LibraryPackageHandoff? Handoff=null);
internal sealed record LibraryPackagesRecord(string SourceKeyRaw,int Revision,LibraryPackageVersion[] Versions);
internal sealed record LibraryPackageCommand(string Key,string ExpectedPackageToken,string Action,string? ExpectedBomToken=null,string? ExpectedDocumentsToken=null,string? ReviewId=null,string? Comments=null,string? PreparationId=null,string? ExpectedPreviewToken=null,string? SubmissionNote=null);
internal sealed partial class SimLibraryBomStore {
 private string PackagePath(string key)=>Path.Combine(root,"packages",Hash(Encoding.UTF8.GetBytes(key))+".json");
 private LibraryPackagesRecord ReadPackages(string key){var path=PackagePath(key);if(!File.Exists(path))return new(key,0,[]);var r=JsonSerializer.Deserialize<LibraryPackagesRecord>(File.ReadAllText(path),Json)!;Require(r.SourceKeyRaw==key,"Package identity verification failed.");foreach(var v in r.Versions)VerifyPackage(v);return r;}
 private static string PackageToken(LibraryPackagesRecord r)=>Hash(JsonSerializer.SerializeToUtf8Bytes(r,Json));
 private static string PackageHash(LibraryPackageVersion v)=>v.Handoff is null?Hash(JsonSerializer.SerializeToUtf8Bytes(new{v.Bom,v.Documents,v.Preparation},Json)):Hash(JsonSerializer.SerializeToUtf8Bytes(new{v.Bom,v.Documents,v.Preparation,v.Handoff},Json));
 private static void VerifyPackage(LibraryPackageVersion v)=>Require(v.ContentHash==PackageHash(v),"Saved package verification failed; no decision was recorded.");
 private bool PackageLocked(LibraryBomRecord bom){var last=ReadPackages(bom.SourceKeyRaw).Versions.LastOrDefault();return last is not null&&(last.Status=="SUBMITTED"||last.Bom.Id==bom.Draft?.Id);}
 private LibraryPackageVersion? ApprovedPackage(string key)=>ReadPackages(key).Versions.LastOrDefault(v=>v.Status=="APPROVED");
 private string? PackageStatus(string key)=>ReadPackages(key).Versions.LastOrDefault()?.Status;
 private async Task WritePackages(LibraryPackagesRecord record){var path=PackagePath(record.SourceKeyRaw);Directory.CreateDirectory(Path.GetDirectoryName(path)!);var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{await File.WriteAllTextAsync(temp,JsonSerializer.Serialize(record,Json));Require(PackageToken(JsonSerializer.Deserialize<LibraryPackagesRecord>(await File.ReadAllTextAsync(temp),Json)!)==PackageToken(record),"Package save verification failed.");File.Move(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
 private async Task<(LibraryDocumentsRecord Record,LibraryDocumentVersion[] Included)> PackageDocuments(string key){var context=await FolderContext(key);var docs=await ReadDocuments(key,context.Drawing,context.Bom);return(docs,docs.History.GroupBy(d=>d.Id).Select(g=>g.MaxBy(d=>d.Version)!).Where(d=>d.Use is "PRODUCTION" or "MATERIALS" or "BOTH").OrderBy(d=>d.Id,StringComparer.Ordinal).ToArray());}
 private string[] PackageBlockers(LibraryBomRecord bom,LibraryDocumentVersion[] documents){var errors=new List<string>();if(bom.Draft is null)errors.Add("Save a BOM draft first.");else errors.AddRange(Blockers(bom.Draft));if(bom.Reviews.Any(r=>r.Status=="SUBMITTED"))errors.Add("Finish or withdraw the existing BOM-only review first.");if(!documents.Any(d=>d.Use is "PRODUCTION" or "BOTH"))errors.Add("Select at least one file for Production before submitting.");return errors.Distinct().ToArray();}
 internal async Task<object> Package(string key,SimPersona p){Permission(p);Header(key);await gate.WaitAsync();try{var packages=ReadPackages(key);var bom=await Read(key);var docs=await PackageDocuments(key);var last=packages.Versions.LastOrDefault();return new{record=packages,packageToken=PackageToken(packages),bomToken=Token(bom),documentsToken=DocumentsToken(docs.Record),bom=bom.Draft,documents=docs.Included,blockers=PackageBlockers(bom,docs.Included),locked=PackageLocked(bom),canEdit=p.Can("assembly_library.edit"),reviewHandoff=true,canStartChanges=last is not null&&last.Status!="SUBMITTED"&&last.Bom.Id==bom.Draft?.Id};}finally{gate.Release();}}
 private async Task<LibraryPackagePreparation?> PackagePreparation(string? id,string key){if(string.IsNullOrEmpty(id))return null;Require(System.Text.RegularExpressions.Regex.IsMatch(id,"^[A-F0-9]{64}$"),"Choose an existing preparation request.");var path=Path.Combine(stateRoot,"library-preparation-v1",id+".json");Require(File.Exists(path),"The preparation request is unavailable.");var r=JsonSerializer.Deserialize<LibraryPreparation>(await File.ReadAllTextAsync(path),Json)!;Require(r.Id==id&&r.LibraryKey==key&&r.Status=="IN_PREPARATION","The preparation request no longer targets this Library assembly.");return new(r.Id,r.ProjectId,r.IntakeId,r.LineNumber,r.DisplayId??r.IntakeId,r.IncomingRevision,r.SourceFingerprint,r.RequestedQuantity,r.RequestedScope);}
 internal async Task<object> ChangePackage(LibraryPackageCommand c,SimPersona p,bool review=false,LibraryPreparation? preparationContext=null,bool readyFlow=false){Permission(p,review,true);if(!review)Header(c.Key);await gate.WaitAsync();try{
  var packages=ReadPackages(c.Key);Require(c.ExpectedPackageToken==PackageToken(packages),"This package changed. Reopen it before continuing.");var actor=Actor(p);
  if(review){Require(c.Action is "APPROVE" or "CHANGES_REQUESTED","Choose Approve or Reject.");Require(c.Comments is null||c.Comments.Length<=4000,"Keep review notes at or below 4000 characters.");var submitted=packages.Versions.SingleOrDefault(v=>v.Id==c.ReviewId&&v.Status=="SUBMITTED");Require(submitted is not null,"This package is no longer awaiting review.");VerifyPackage(submitted!);await VerifyEvidence(submitted!.Bom);foreach(var doc in submitted.Documents)await PackageEvidenceBytes(doc);
   if(c.Action=="APPROVE")Require(Blockers(submitted.Bom).Length==0,string.Join(" ",Blockers(submitted.Bom)));else Require(!string.IsNullOrWhiteSpace(c.Comments),"Add notes describing the changes needed before rejecting.");
   packages=packages with{Revision=packages.Revision+1,Versions=packages.Versions.Select(v=>v.Id==submitted.Id?v with{Status=c.Action=="APPROVE"?"APPROVED":"CHANGES_REQUESTED",ReviewedBy=actor,Comments=Text(c.Comments,4000)}:v).ToArray()};await WritePackages(packages);return new{record=packages,packageToken=PackageToken(packages)};
  }
  Require(c.Action is "SUBMIT" or "START_CHANGES" or "WITHDRAW","Unsupported package action.");var bom=await Read(c.Key);Require(c.ExpectedBomToken==Token(bom),"The saved BOM changed. Refresh the package summary before submitting.");var last=packages.Versions.LastOrDefault();
  if(c.Action=="START_CHANGES"){
   Require(last is not null&&last.Status!="SUBMITTED"&&bom.Draft is not null&&last.Bom.Id==bom.Draft.Id,"A working version already exists or is still under review.");VerifyPackage(last!);
   var draft=bom.Draft! with{Id=Guid.NewGuid().ToString(),InternalVersion=Math.Max(NextVersion(bom),packages.Versions.Max(v=>v.Bom.InternalVersion)+1),Author=actor,SavedBy=actor};
   await Write(bom with{Revision=bom.Revision+1,Draft=draft,History=[..bom.History,new("PACKAGE_REVISION",draft.Id,actor,"From package "+last!.Version)]});
   return new{record=packages,packageToken=PackageToken(packages)};
  }
  if(c.Action=="WITHDRAW"){
   Require(last is not null&&last.Status=="SUBMITTED","Only a submitted package can be withdrawn.");packages=packages with{Revision=packages.Revision+1,Versions=packages.Versions.Select(v=>v.Id==last!.Id?v with{Status="WITHDRAWN",WithdrawnBy=actor,Comments=Text(c.Comments,4000)}:v).ToArray()};await WritePackages(packages);return new{record=packages,packageToken=PackageToken(packages)};
  }
  LibraryReadyState? ready=null;
  if(readyFlow){Require(!string.IsNullOrWhiteSpace(c.ExpectedPreviewToken),"Open Ready for review before submitting.");ready=await BuildReadyState(c.Key,packages,bom,await PackageDocuments(c.Key),preparationContext);Require(ready.PreviewToken==c.ExpectedPreviewToken,"The review summary changed. Reopen Ready for review before submitting; nothing was submitted.");Require(c.SubmissionNote is null||c.SubmissionNote.Length<=2000,"Keep the submission note at or below 2000 characters.");}
  Require(!PackageLocked(bom),"This version is fixed. Start changes or withdraw it before submitting another version.");var docs=await PackageDocuments(c.Key);Require(c.ExpectedDocumentsToken==DocumentsToken(docs.Record),"The selected files changed. Refresh the package summary before submitting.");var blockers=PackageBlockers(bom,docs.Included);Require(blockers.Length==0,string.Join(" ",blockers));Require(docs.Included.Length<=50,"Use up to 50 identified files per package.");await VerifyEvidence(bom.Draft!);
  var prepared=new List<(LibraryPackageDocument Document,byte[] Bytes)>();long size=0;
  foreach(var doc in docs.Included){Require(doc.Association.SourceKeyRaw==c.Key&&doc.Association.DrawingRevision==bom.Draft!.DrawingRevision&&doc.Association.BomRevision==bom.Draft.BomRevision,"A selected file belongs to another assembly revision.");var file=await ReadDocumentFile(doc.Association,doc.Source.RelativePath);Require(file.Source.SourceToken==doc.Source.SourceToken&&file.Source.Sha256==doc.Source.Sha256,"Selected file changed: "+file.Name+". Review and save its identification again.");size+=file.Bytes.LongLength;Require(size<=100L*1024*1024,"Keep the selected package at or below 100 MB.");prepared.Add((new(doc,file.Source.Sha256),file.Bytes));}
  var preparation=readyFlow?ready!.Summary.Request:string.IsNullOrEmpty(c.PreparationId)?last?.Preparation:await PackagePreparation(c.PreparationId,c.Key);
  var snapshot=new LibraryPackageVersion(Guid.NewGuid().ToString(),packages.Versions.Length+1,"SUBMITTED",bom.Draft!,prepared.Select(d=>d.Document).ToArray(),"",actor,preparation,Handoff:readyFlow?new(1,ready!.Summary,string.IsNullOrWhiteSpace(c.SubmissionNote)?null:c.SubmissionNote.Trim(),ready.PreparationToken,ready.CopyReceiptsToken,ready.BomToken,ready.DocumentsToken):null);snapshot=snapshot with{ContentHash=PackageHash(snapshot)};
  foreach(var file in prepared){var dir=Path.Combine(root,"package-evidence");Directory.CreateDirectory(dir);var path=Path.Combine(dir,file.Document.EvidenceHash);if(File.Exists(path)){Require(Hash(await File.ReadAllBytesAsync(path))==file.Document.EvidenceHash,"Existing package copy failed verification.");continue;}var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{await File.WriteAllBytesAsync(temp,file.Bytes);Require(Hash(await File.ReadAllBytesAsync(temp))==file.Document.EvidenceHash,"Package copy verification failed.");File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  packages=packages with{Revision=packages.Revision+1,Versions=[..packages.Versions,snapshot]};await WritePackages(packages);return new{record=packages,packageToken=PackageToken(packages)};
 }finally{gate.Release();}}
 private async Task<byte[]> PackageEvidenceBytes(LibraryPackageDocument document){Require(System.Text.RegularExpressions.Regex.IsMatch(document.EvidenceHash,"^[A-F0-9]{64}$"),"Invalid saved document hash.");var bytes=await File.ReadAllBytesAsync(Path.Combine(root,"package-evidence",document.EvidenceHash));Require(Hash(bytes)==document.EvidenceHash,"Saved document verification failed.");return bytes;}
 internal async Task<object> PackageQueue(SimPersona p){Permission(p,review:true);await gate.WaitAsync();try{var path=Path.Combine(root,"packages");var items=new List<object>();if(Directory.Exists(path))foreach(var file in Directory.EnumerateFiles(path,"*.json")){var record=JsonSerializer.Deserialize<LibraryPackagesRecord>(await File.ReadAllTextAsync(file),Json)!;foreach(var v in record.Versions.Where(v=>v.Status=="SUBMITTED")){VerifyPackage(v);items.Add(new{key=record.SourceKeyRaw,packageToken=PackageToken(record),version=v});}}return new{items,canReview=p.Can("technical_review.disposition"),finalReviewRoundtrip=true};}finally{gate.Release();}}
 internal async Task<object> PackageFile(string key,string reviewId,string documentId,SimPersona p,bool review){Permission(p,review);await gate.WaitAsync();try{var v=ReadPackages(key).Versions.SingleOrDefault(v=>v.Id==reviewId);Require(v is not null,"Saved package unavailable.");VerifyPackage(v!);if(documentId=="_bom-source"){Require(v!.Bom.EvidenceHash is not null,"No TXT source is attached.");await VerifyEvidence(v.Bom);return new{name=v.Bom.EvidenceName??"bom.txt",base64=await EvidenceBase64(v.Bom)};}var doc=v!.Documents.SingleOrDefault(d=>d.Identification.Id==documentId);Require(doc is not null,"Document is not part of this submitted package.");return new{name=Path.GetFileName(doc!.Identification.Source.RelativePath),base64=Convert.ToBase64String(await PackageEvidenceBytes(doc))};}finally{gate.Release();}}
}
